package com.avizero.avidrive.api;

import com.avizero.avidrive.domain.Setting; import com.avizero.avidrive.domain.User; import com.avizero.avidrive.repository.SettingRepository; import com.avizero.avidrive.repository.UserRepository; import com.avizero.avidrive.security.AuthUser; import java.util.*; import org.springframework.http.ResponseEntity; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class QuotaController {private final UserRepository users;private final SettingRepository settings;public QuotaController(UserRepository u,SettingRepository s){users=u;settings=s;}
 @GetMapping("/quota") public Map<String,Object> quota(Authentication a){User user=users.findById(((AuthUser)a.getPrincipal()).id()).orElseThrow();Setting s=settings.findById(1L).orElseThrow();long globalUsed=users.findAll().stream().mapToLong(x->x.usedBytes==null?0:x.usedBytes).sum();return Map.of("used_bytes",value(user.usedBytes),"quota_mb",value(user.quotaMb),"user_threshold",threshold(user.usedBytes,user.quotaMb,80,90,100),"global_used_bytes",globalUsed,"global_quota_mb",value(s.globalQuotaMb),"global_threshold",threshold(globalUsed,s.globalQuotaMb,95,100,null));}
 @PatchMapping("/admin/settings/global-quota") public ResponseEntity<?> update(@RequestBody Map<String,Long> body,Authentication a){if(!"ADMIN".equals(((AuthUser)a.getPrincipal()).role()))return ResponseEntity.status(403).body(Map.of("message","Недостаточно прав"));long quota=body.getOrDefault("global_quota_mb",0L);if(quota<0)return ResponseEntity.badRequest().body(Map.of("message","Квота не может быть отрицательной"));Setting s=settings.findById(1L).orElseThrow();s.globalQuotaMb=quota;settings.save(s);return ResponseEntity.ok(Map.of("global_quota_mb",quota));}
 private long value(Long n){return n==null?0:n;}private Integer threshold(long used,Long quota,Integer low,Integer high,Integer full){if(quota==null||quota==0)return null;long percent=used*100/(quota*1024*1024);return percent>=100?(full==null?100:full):percent>=high?high:percent>=low?low:null;}}
